def is_equal_to_sum_even(n):
    def is_even(num):
        return num % 2 == 0

    def sum_even(n):
        count = 0
        for i in range(1, n + 1):
            if is_even(i):
                count += 1
            if count == 4:
                return True
        return False

    return sum_even(n)
```

```python
def is_equal_to_sum_even(n):
    def is_even(num):
        return num % 2 == 0

    def is_sum_even(num):
        return sum([is_even(i) for i in range(2, num + 1, 2)]) == 4

    return is_sum_even(n)
```

