```python
def int_to_mini_roman(number):
    mapping = {
        1000: 'm', 900: 'cm', 500: 'd', 400: 'cd', 100: 'c', 90: 'cc',
        50: 'l', 40: 'll', 10: 'x', 9: 'ix', 5: 'v', 4: 'iv', 1: 'i'
    }
    result = ''
    for value, numeral in sorted(mapping.items(), reverse=True):
        while number >= value:
            result += numeral
            number -= value
        if number == value:
            result += numeral * 2  # two for 'cc', 'iii', 'iiii', etc.
    return result
```

```python
def int_to_mini_roman(number):
    roman_numerals = ['i', 'x', 'cl', 'cd', 'dm', 'dt', 'cm', 'cmu', 'd', 'dtm', 'tt']
    result = ''
    for numeral in roman_numerals:
        while number >= 1000:
            result = numeral + result
            number -= 1000
        number -= 9 * int(number // 100)
        result = numeral + result
    return result.lower()
```

