from typing import List

def factorize(n: int) -> List[int]:
    def prime_factors(n: int) -> List[int]:
        i = 2
        factors = []
        while i * i <= n:
            if n % i:
                i += 1
            else:
                n //= i
                factors.append(i)
        if n > 1:
            factors.append(n)
        return factors

    n_factors = prime_factors(n)
    return sorted(n_factors)
```

