def pluck(arr):
    if not arr:
        return []
    min_even = float('inf')
    min_index = float('inf')
    for i, node in enumerate(arr):
        if node % 2 == 0:
            if node < min_even:
                min_even = node
                min_index = i
            elif node == min_even:
                min_index = i
    return [min_even, min_index]
