    primes = [True] * (int(math.pow(string, 0.5)) + 1)
    primes[0], primes[1] = False, False
    for index, present in enumerate(primes):
        if present:
            for possiblePrime in range(index + 1, int(math.pow(string, 0.5)) + 1):
                if primes[possiblePrime]:
                    primes[possiblePrime] = False
    for index in range(2, len(primes)):
        if primes[index]:
            return True
    return False
