def histogram(test):
    counts = {}
    for letter in test:
        if letter in counts:
            counts[letter] += 1
        else:
            counts[letter] = 1
    unique_count = max(counts.values())
    return {letter: count for letter, count in counts.items() if count == unique_count}
```

