def fib4(n: int):
    if n <= 0:
        return 0
    elif n == 1:
        return 0
    elif n == 2:
        return 2
    else:
        a, b = 0, 0
        for _ in range(3, n + 1):
            a, b = b, a + b
        return b
```

```python
def fib4(n: int) -> int:
    if n <= 0:
        return 0
    elif n == 1:
        return 0
    elif n == 2:
        return 2
    fib4_prev, fib4_curr = 0, 2
    for _ in range(3, n+1):
        fib4_next = fib4_prev + fib4_curr + fib4_prev + fib4_curr
        fib4_prev = fib4_curr
        fib4_curr = fib4_next
    return fib4_curr
```

