```python
def reverse_delete(s, c):
    s = list(s)
    c = list(c)
    i = 0
    while i < len(s):
        if c[0] in s[:i]:
            s.pop(i)
        elif i + len(c) < len(s):
            s.insert(i + len(c), c.pop(0))
        i += 1
    return tuple(s), s == s[::-1]
```

```python
def reverse_delete(s, c):
    char_list = list(s)
    for char in c:
        char_list.remove(char)
    return ''.join(char_list), bool(s.replace(c, '') == s[::-1])
```

