        if x < 2:
            return False
        for i in range(2, int(x**0.5) + 1):
            if x % i == 0:
                return False
        return True

    fib_nums = [0, 1]
    while len(fib_nums) <= n:
        fib_num = fib_nums[-1] + fib_nums[-2]
        if is_prime(fib_num):
            fib_nums.append(fib_num)

