def smallest_change(arr):
    n = len(arr)
    dp = [[False] * n for _ in range(n)]

    for i in range(n):
        dp[i][i] = True

    for k in range(1, n):
        for i in range(n-k):
            j = i + k
            if arr[i] == arr[j]:
                dp[i][j] = dp[i+1][j-1]
            else:
                dp[i][j] = dp[i+1][j] or dp[i][j-1]

    for i in range(n):
        if dp[0][i]:
            return i - 1

    return 0
```

