def smallest_change(arr):
    def is_palindromic(subarr):
        return subarr == subarr[::-1]

    res = float('inf')
    for i in range(len(arr)):
        for j in range(i + 1, len(arr)):
            subarr = arr[i:j]
            if is_palindromic(subarr):
                res = min(res, j - i)
    return res
```

