import itertools

def compare(arr1, arr2):
    result = []
    for guess in itertools.product(range(arr2[-1] + 1), repeat=len(arr1)):
        if arr1 == arr2:
            result.append(0)
        elif arr1 == (-1) * arr2:
            result.append((-1) * abs(guess if guess >= 0 else arr2[-1] - guess))
        else:
            result.append(abs(guess if guess >= 0 else arr2[-1] - guess))
    return result
```

