def is_multiply_prime(a):
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    factors = 2
    while a > 1:
        if a % factors == 0 and is_prime(factors):
            a = a // factors
        else:
            factors += 1
    return a == 1
```

