import math

def is_multiply_prime(a):
    def is_prime(x):
        if x < 2:
            return False
        for i in range(2, int(math.sqrt(x)) + 1):
            if x % i == 0:
                return False
        return True

    if a <= 0:
        return False

    primes = []
    for i in range(2, a + 1):
        if is_prime(i):
            if a // i in primes:
                return True
            else:
                primes.append(i)

    return False
```

```python
def is_multiply_prime(a):
    def is_prime(x):
        if x < 2:
            return False
        for i in range(2, int(x**0.5) + 1):
            if x % i == 0:
                return False
        return True

    primes = [2, 3, 5]
    while a > 1 and a // primes[-1] > 0:
        num = a % primes[-1]
        if num not in [p for p in primes if p <= num]:
            a //= primes[-1]
        else:
            a //= primes[-1]
            primes.remove(primes[-1])
    return a == 1
```

