def circular_shift(x, shift):
    str_x = str(x)
    result = []

    for i in range(len(str_x)):
        if i <= shift:
            result.append(str_x[i] + str_x[i + shift])
        elif i > len(str_x) - shift:
            result.append(str_x[i - shift] + str_x[i])
        else:
            result.append(str_x[i - shift] + str_x[i])

    return ''.join(result)
```

