import math

def is_multiply_prime(a):
    factors = []
    for i in range(2, int(math.sqrt(a)) + 1):
        if a % i == 0:
            factors.append(i)
            if i != a // i:
                factors.append(a // i)
    return len(factors) == 3 and all(math.gcd(x, y) == 1 for x in factors for y in factors if x != y)
