import math

def is_multiply_prime(a):
    def is_prime(n):
        if n <= 1:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        sqrt_n = math.sqrt(n)
        for i in range(3, int(sqrt_n) + 1, 2):
            if n % i == 0:
                return False
        return True

    count = 0
    for i in range(3, a):
        if is_prime(i) and a % i == 0 and is_prime(a // i):
            count += 1
    return count <= 2
```

