def is_nested(string):
    stack = []
    brackets_map = {']': '(', '$': '{', ']': '['}

    for bracket in string:
        if bracket in brackets_map.values():
            stack.append(bracket)
        elif bracket in brackets_map.keys():
            if not stack or stack.pop() != brackets_map[bracket]:
                return False

    return len(stack) == 0
