import random

def strange_sort_list(lst):
    if len(lst) == 0:
        return lst

    reversed_list = lst[:]
   isers = random.sample(range(len(lst)), len(lst))

    idx = 0
    key = reversed_list[isers[0]]
    for num in reversed_list[isers[1:]]:
        while idx < len(num):
            if abs(num - key) > abs(num - reversed_list[idx]):
                reversed_list[idx], reversed_list[isers[0]] = reversed_list[isers[0]], reversed_list[idx]
            idx += 1

    return reversed_list
```

