def minSubArraySum(nums):
    result = float('inf')
    for i in range(len(nums)):
        currentSum = 0
        for j in range(i, len(nums)):
            currentSum += nums[j]
            result = min(result, currentSum)
            if currentSum < 0:
                currentSum = 0
    return result if result != float('inf') else -1
