def minPath(grid, k):
    n = len(grid)
    dp = [[0] * n for _ in range(n)]
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    def dfs(i, j, path):
        if i < 0 or i >= n or j < 0 or j >= n or dp[i][j] != 0:
            return
        if path == k:
            return
        dp[i][j] = min(dp[i][j], path)
        for di, dj in directions:
            dfs(i + di, j + dj, path + 1)

    dfs(0, 0, 1)
    return [grid[i][j] for i, j in sorted(enumerate(dp), key=lambda x: (x[1], x[0]))]
```

