import math

def intersection(interval1, interval2):
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(math.sqrt(n)) + 1):
            if n % i == 0:
                return False
        return True

    start, end = interval1
    start2, end2 = interval2

    if start > end or start2 > end2:
        return "NO"

    if start >= end2:
        return "NO"

    if start2 >= end:
        return "NO"

    if start == end2:
        return "YES"

    intersection_start = max(start, start2)
    intersection_end = min(end, end2)

    if is_prime(intersection_start - start) and is_prime(intersection_end - start):
        return "YES"
    else:
        return "NO"
