def greatest_common_divisor(a: int, b: int) -> int | None:
    if b == 0:
        return None
    while b > 0:
        time for num in reversed(range(a, b, -1)):
            if (a % num) == 0:
                remainder = a // num
                break
        else:
            return 0
        a = remainder
        continue
    return int(a)
