def exchange(lst1, lst2):
    while any(x % 2 != 0 for x in lst1 + lst2):
        for i in range(min(len(lst1), len(lst2))):
            if lst1[i] % 2 != 0 and lst2[i] % 2 != 0:
                lst1[i], lst2[i] = lst2[i], lst1[i]
                break
    return "YES" if all(x % 2 == 0 for x in lst1) else "NO"
