import math

def prime_length(string):
    def is_prime(n):
        """Check if a number is prime"""
        if n <= 1:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        sqrt_n = math.sqrt(n)
        for i in range(3, int(sqrt_n) + 1, 2):
            if n % i == 0:
                return False
        return True

    return any(is_prime(len(s)) for s in string)
```

