def skjkasdkd(lst):
    def is_prime(n):
        if n <= 1:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        i = 3
        while i * i <= n:
            if n % i == 0:
                return False
            i += 2
        return True

    max_num = max(lst)
    for num in lst:
        if is_prime(num) and num > max_num:
            max_num = num
    return sum(int(digit) for digit in str(max_num))
```

