def skjkasdkd(lst):
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                return False
        return True

    max_prime = 0
    for num in lst:
        if is_prime(num):
            max_prime = max(max_prime, num)
    return sum(int(digit) for num in lst for digit in str(num) if is_prime(num))

