def file_name_check(file_name):
    if len(file_name) > 3 or not file_name[0].isalpha():
        return 'No'
    elif file_name.count('.') == 1 and not file_name[0].isalpha() and not file_name[1:].isalpha():
        return 'No'
    elif file_name.count('.') == 1 and not file_name[0].isalpha() and file_name[1:].isalpha():
        return 'No'
    elif file_name.count('.') == 1 and not file_name[0].isalpha() and file_name[1:] == ['txt', 'exe', 'dll']:
        return 'Yes'
    elif file_name.count('.') == 2 and file_name[0] in ['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i', 'j', 'k', 'l', 'm', 'n', 'o', 'p', 'q', 'r', 's', 't', 'u', 'v', 'w', 'x', 'y', 'z'] and file_name[1:].isalpha():
        return 'Yes'
    else:
        return 'No'
