```python
def find_max(words):
    word_counts = {}
    max_word = ""
    max_count = 0

    for word in words:
        unique_chars = set(word)
        if len(unique_chars) > max_count:
            max_word = word
            max_count = len(unique_chars)
        elif len(unique_chars) == max_count:
            max_word = word if word <= max_word else word

    return max_word if max_count > 0 else ""
```

