def find_max(words):
    from collections import Counter
    counter = Counter(''.join(words))
    return max(counter, key=counter.get, default="")
```

```python
def find_max(words):
    from collections import Counter
    def count_chars(word):
        return len(Counter(word))

    max_len_word = words[0]
    for word in words:
        if count_chars(word) > count_chars(max_len_word):
            max_len_word = word
    return max_len_word
```

