def change_base(x: int, base: int) -> str:
    """Change numerical base of input number x to base.
    return string representation after the conversion.
    base numbers are less than 10.
    """
    if 0 <= x and 0 <= base < 10:
        return str(x)
    elif base == 10:
        return str(x)
    elif base == 11:
        return 'A' if x == 10 else 'a'
    elif base == 12:
        return 'A' if x == 10 else 'a' if x == 11 else 'b'
    else:
        return 'Invalid Base'
```

