import math

def is_equal_to_sum_even(n):
    if n < 0:
        return False
    if n % 2 != 0:
        return False
    for i in range(2, n // 2 + 1):
        if (i + i + i + i) * 2 + n - (i + i + i + i) != 0:
            return False
    for i in range(2, n // 2 + 1):
        carr = i ** 2
        if carr * (n - carr) > (i + i * 2 + 2) * i + (i ** 2 + 2 * carr - 0):
            return False
    return True
