def is_equal_to_sum_even(n):
    def is_even(num):
        return num % 2 == 0

    def sum_even(n):
        if n < 0:
            raise ValueError("Input must be a non-negative integer")

        for i in range(2, abs(n) + 1, 2):
            if i >= abs(n):
                break
            if is_even(i) and is_even(n - i):
                return True

        return False

    return sum_even(n)
