import math

def is_multiply_prime(a):
    def is_prime(x):
        if x < 2:
            return False
        for i in range(2, int(math.sqrt(x)) + 1):
            if x % i == 0:
                return False
        return True

    def multiply_primes(n):
        for i in range(2, n):
            if n % i == 0 and is_prime(i) and is_prime(n // i):
                return True
        return False

    return multiply_primes(a)
```

