def minPath(grid, k):
    n = len(grid)
    dp = [[0] * n for _ in range(n)]
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    def dfs(i, j, path):
        if i < 0 or i >= n or j < 0 or j >= n or path[-1] > grid[i][j]:
            return
        if dp[i][j] != 0:
            return
        dp[i][j] = path[-1]
        for di, dj in directions:
            dfs(i + di, j + dj, path + [grid[i][j]])

    dfs(0, 0, [grid[0][0]])
    return dp[n - 1][n - 1]

