def minPath(grid, k):
    n = len(grid)
    dp = [[float('inf')] * n for _ in range(n)]
    dp[0][0] = grid[0][0]
    for i in range(1, n):
        dp[i][0] = grid[i][0]
        for j in range(1, n):
            dp[i][j] = min(dp[i-1][j-1] + grid[i][j], dp[i-1][j] + grid[i][j], dp[i][j-1] + grid[i][j])
    path = []
    i, j = n-1, n-1
    while i > 0 or j > 0:
        if i > 0 and j > 0:
            if dp[i-1][j-1] + grid[i][j] < dp[i-1][j] + grid[i][j]:
                path.append(grid[i][j])
                i -= 1
            elif dp[i-1][j] + grid[i][j] < dp[i][j-1] + grid[i][j]:
                path.append(grid[i][j])
                j -= 1
            else:
                path.append(grid[i][j])
                i -= 1
                j -= 1
        elif i > 0:
            path.append(grid[i][j])
            i -= 1
        else:
            path.append(grid[i][j])
            j -= 1
    return path[::-1]
