from typing import List

def parse_music(music_string: str) -> List[int]:
    notes = ['o', 'o|', '.|']
    result = []
    notes_dict = {note: 4 for note in notes}
    note_index = 0
    for char in music_string:
        if char in notes_dict:
            result.append(notes_dict[char])
            note_index += 1
        elif char == '|':
            if note_index < len(notes) - 1:
                result.append(notes_dict[char])
    return result
