    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(math.sqrt(n)) + 1):
            if n % i == 0:
                return False
        return True

    start, end = interval1
    start2, end2 = interval2

    if start > end2 or start2 > end:
        return "NO"

    if start >= end2 and start <= end:
        return "YES" if is_prime(end - start) else "NO"

    if start2 < end and start >= end2:
        return "YES" if is_prime(end - start2) else "NO"

