import re

def get_closest_vowel(word):
    closest_vowel = ""
    for i in range(len(word) - 1, -1, -1):
        match = re.search('[aeiou]', word[i:])
        if match:
            if closest_vowel == "":
                closest_vowel = match.group()
            else:
                if abs(match.start() - closest_vowel.start()) < abs(match.end() - closest_vowel.end()):
                    closest_vowel = match.group()
    return closest_vowel
