import math

def count_up_to(n):
    primes = []
    for i in range(2, n + 1):
        is_prime = True
        for j in range(2, int(math.sqrt(i)) + 1):
            if i % j == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(i)
    return primes
```

```python
def largest_prime_factor(n: int):
    i = 2
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
    return n
```

```python
def largest_prime_factor(n: int) -> int:
    for i in range(2, int(n**0.5) + 1):
        while n % i == 0:
            n = n // i
    if n > 1:
        return n
    else:
        return 1
