def prime_fib(n: int):
    """
    prime_fib returns n-th number that is a Fibonacci number and it's also prime.
    """
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
        if a > 1 and is_prime(a):
            return a
    return None

def is_prime(num: int) -> bool:
    """
    is_prime checks if a number is prime.
    """
    if num < 2:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True
```

