from typing import List
import collections

def parse_nested_parens(paren_string: str) -> List[int]:
    stack = collections.deque()
    output = []
    curr_level = 0
    for char in parse_nested_parens_parens(paren_string):
        if char == '(':
            stack.append(char)
            curr_level += 1
            output.append(curr_level)
        elif char == ')':
            stack.pop()
            if not stack:  # It means all parentheses around the current level are closed
                curr_level -= 1
            else:
                curr_level = 0
    return output

def parse_nested_parens_parens(paren_string: str) -> str:
    stack = ['']
    output = []
    index = 0
    while index < len(paren_string):
        if index + 1 < len(paren_string) and paren_string[index + 1] == '(':
            stack.append(paren_string[index])
            output.append(stack[-1])
            index += 2
        elif index + 1 < len(paren_string) and paren_string[index + 1] == ')':
            stack.pop()
            output.append(stack[-1])
            index += 2
        elif index < len(paren_string) and paren_string[index] == ')':
            index += 1
        elif index < len(paren_string) and paren_string[index] == '(':
            index += 1
    return ''.join(str(x) for x in output[::-1][1:])
