def closest_integer_lower(value):
    min_diff = abs(value - [0, -1, 1, 2, 20])
    for d in min_diff:
        v = value + d
        abs_diff = abs(v - [0, -1, 1, 2, 20])
        return v if abs_diff == min_diff else value

def closest_integer_upper(value):
    min_diff = abs(value - [1, 2, 20])
    for d in min_diff:
        v = value + d
        abs_diff = abs(v - [1, 2, 20])
        return v if abs_diff == min_diff else value

def closest_integer(value):
    return closest_integer_lower_closest(value)

def closest_integer(value):
    return closest_integer_upper_closest(value)
