import math

def max_fill(grid, capacity):
    rows, cols = len(grid), len(grid[0])
    buckets = [[0] * cols for _ in range(rows)]
    max_fill_count = 0

    for row in range(rows):
        for col in range(cols):
            if grid[row][col] == 1:
                buckets[row][col] = 1
                max_fill_count += 1

    for row in range(rows):
        for col in range(cols):
            if buckets[row][col] == 0:
                continue
            for next_row in range(rows):
                for next_col in range(cols):
                    if buckets[next_row][next_col] == 0:
                        continue
                    if buckets[next_row][next_col] == 1:
                        buckets[row][col] = 0
                        buckets[next_row][next_col] = 0
                        max_fill_count += 1
                        break
                if max_fill_count > capacity:
                    break

    return max_fill_count
```

