def max_fill(grid, capacity):
    n, m = len(grid), len(grid[0])
    ans = 0

    while True:
        for i in range(n):
            for j in range(m):
                if grid[i][j] == 1:
                    bucket = min(n - i, m - j)
                    if bucket <= capacity:
                        ans += bucket
                        grid[i][j] = 0
                        capacity -= bucket
                    else:
                        break

        if not any(grid[i][j] for i in range(n) for j in range(m)):
            break

    return ans
