import math

def max_fill(grid, capacity):
    n, m = len(grid), len(grid[0])
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if grid[i - 1][j - 1] == 0:
                dp[i][j] = dp[i - 1][j]
            else:
                dp[i][j] = min(dp[i - 1][j], dp[i][j - 1]) + 1

    ans = 0
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if grid[i - 1][j - 1] == 1:
                ans += dp[i][j] * capacity
    return ans
```

