import math

def max_fill(grid, capacity):
    rows, cols = len(grid), len(grid[0])
    buckets = [[0]*cols for _ in range(rows)]
    res = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1:
                buckets[i][j] = capacity
                res += 1
    max_fill_recursive(grid, buckets, capacity, rows, cols, 0, res)
    return res

def max_fill_recursive(grid, buckets, capacity, rows, cols, i, res):
    if i == rows:
        return
    if buckets[i][0] == capacity:
        res += 1
        return
    if buckets[i][0] < capacity:
        buckets[i][0] += 1
        max_fill_recursive(grid, buckets, capacity, rows, cols, i + 1, res)
    max_fill_recursive(grid, buckets, capacity, rows, cols, i + 1, res)
```

