import math

def max_fill(grid, capacity):
    rows, cols = len(grid), len(grid[0])
    buckets = [0] * rows
    ans = 0

    for row in range(rows):
        for col in range(cols):
            if grid[row][col] == 1:
                buckets[row] += 1

    for bucket in range(rows):
        while buckets[bucket] > 0 and capacity > 0:
            while buckets[bucket] > 0 and capacity > 0:
                buckets[bucket] -= 1
                capacity -= 1
            ans += 1

    return ans
