def exchange(lst1, lst2):
    def helper(lst1, lst2, used, even):
        if len(lst1) == 0 and len(lst2) == 0 and all(x % 2 == 0 for x in lst1):
            return "YES"
        if len(lst1) == 0 and len(lst2) != 0 and all(x % 2 == 0 for x in lst2):
            return "YES"
        if len(lst1) != 0 and len(lst2) == 0 and all(x % 2 == 0 for x in lst2):
