        if len(lst1) != 0 and len(lst2) != 0 and (not used and all(x % 2 == 0 for x in lst1)) or (used and all(x % 2 == 0 for x in lst2)):
            if helper(lst1[1:], lst2[1:], used | 1, even):
                return "YES"
            elif helper(lst1[1:], lst2[1:], used | 2, even):
                return "YES"
        return "NO"
    return helper(lst1, lst2, 0, False)

