def hex_key(num):
    def is_prime(n):
        if n <= 1:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        sqrt_n = int(n**0.5) + 1
        for i in range(3, sqrt_n, 2):
            if n % i == 0:
                return False
        return True

    def count_hex_digits(n):
        return sum(c.isdigit() for c in n)

    return count_hex_digits(num) + 3 if num else 0


# Example usage:
print(hex_key("AB"))
print(hex_key("1077E"))
print(hex_key("ABED1A33"))
print(hex_key("123456789ABCDEF0"))
print(hex_key("2020"))
```

```python
def hex_key(num):
    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    hex_digits = [c for c in num if c in '0123456789ABCDEF']
    prime_count = sum(1 for digit in hex_digits if is_prime(int(digit, 16)))
    return prime_count
```

