import re

def encode(message):
    vowels = 'aeiouAEIOU '
    result = '' 
    for c in message:
        if c.isalpha(): 
            index_vowels = vowels.index(c.lower())
            if c.isupper():
                result += vowels[(index_vowels - 2) % 26].upper()
            else:
                result += vowels[(index_vowels + 2) % 26]
        else:
            result += c 
    return result
```

