import string

def encode(message):
    result = ''
    for char in message:
        if char.lower() in string.ascii_lowercase:
            index = string.ascii_lowercase.index(char.lower())
            if char.isupper():
                result += string.ascii_lowercase[(index + 2) % 26]
            else:
                result += string.ascii_lowercase[(index + 2) % 26]
        else:
            result += char
    return result
```

