import re

def get_closest_vowel(word):
    closest_vowel = ""
    for i in range(len(word) - 1, -1, -1):
        if re.search(r'[aeiou]', word[i]):
            if closest_vowel == "":
                closest_vowel = word[i]
            else:
                if abs(ord(word[i]) - ord(closest_vowel)) < abs(ord(word[i + 1]) - ord(closest_vowel)):
                    closest_vowel = word[i]
    return closest_vowel
