import math

def poly(xs: list, x: float):
    """
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[2] * x^2 + .... xs[n] * x^n
    """
    return sum([coeff * math.pow(x, i) for i, coeff in enumerate(xs)])

def find_zero(xs: list):
    """
    finds x for given polynomial equation with rhete Ans: Poly(x) = 0
    takes list xs with even number of coefficients and largest non-zero coeff
    returns float, in case of multiple solutions
    """
    for i in range(len(xs)):
        if xs[i] != 0:
            return round(xs[i] / (math.pow(x, i)), 2)
    return -1.0 if xs[0] else float('inf')
```

