def sum_squares(lst):
    result = 0
    for i, num in enumerate(lst):
        if i % 3 == 0 and i not in [4*n for n in range(1,5)]:
            result += num ** 2
        elif i % 4 == 0 and i % 3 in [4*n for n in range(1,5)] and i not in [4*n for n in range(1,5)]:
            result += round(num ** 3)
    return result
