import re

def select_words(s, n):
    words = re.findall(r'\b\w\S*\b', s)
    consonant_counts = {}
    for word in words:
        for char in word:
            char_lower = char.lower()
            if char_lower.isalpha():
                if char_lower in 'aeiou':
                    consonant_counts[char.upper()] = consonant_counts.get(char_upper, 0) + 1
    select_words = [word for word, count in consonant_counts.items() if count == n and word.lower().isalpha()]

    if not select_words:
        return []

    return select_words
