```python
def largest_prime_factor(n: int):
    def get_prime_factors(num: int) -> list[int]:
        i = 2
        factors = []
        while i * i <= num:
            if num % i:
                i += 1
            else:
                num //= i
                factors.append(i)
        if num > 1:
            factors.append(num)
        return factors

    return max(get_prime_factors(n))
```

