def file_name_check(file_name):
    file_name = file_name.strip()
    file_name = file_name.replace('.', '')
    if len(file_name) > 3 or len(file_name) < 1:
        return 'No'
    elif not any(char.isalpha() for char in file_name):
        return 'No'
    elif file_name[:3] not in ['txt', 'exe', 'dll']:
        return 'No'
    else:
        return 'Yes'
```

