```python
def compare_one(a, b):
    if isinstance(a, (int, float)):  # int or float
        if isinstance(b, (int, float)):
            return max(a, b)
        else:
            return a
    elif isinstance(a, str):  # string
        try:
            b = float(b)  # Convert string to float
            return max(a, b)
        except ValueError:
            return a
    else:
        return None
```

