def exchange(lst1, lst2):
    stack1, stack2 = lst1, lst2
    so_far = []

    while stack1 or stack2:
        if stack1:
            while stack2:
                if not so_far or so_far[-1] % 2 != stack2.pop():
                    break
            if not so_far:
                return "NO"
            so_far.append(stack1.pop())
        if stack2:
            while so_far:
                if not stack1 or stack1[-1] % 2 != so_far.pop():
                    break
            if not so_far:
                return "NO"
            so_far.append(stack2.pop())
    return "YES" if so_far else "NO"
```

