def largest_prime_factor(n: int):
    def largest_prime_factor_helper(x):
        """Helper function to check if a number is prime."""
        if x < 2:
            return False
        for i in range(2, int(x**0.5) + 1):
            if x % i == 0:
                return False
        return True

    for x in range(n, 1, -1):
        while x % num = 0:
            if largest_prime_factor_helper(num):
                return num
    return None
```

```python
def largest_prime_factor(n: int):
    def prime_factors(x):
        if x % 2 == 0:
            yield 2
        i = 3
        while i * i <= x:
            if x % i:
                i += 2
            else:
                x //= i
                yield i
        if x > 2:
            yield x

    max_prime = 1
    for factor in prime_factors(n):
        max_prime = max(max_prime, factor)
    return max_prime

```

