def minPath(grid, k):
    n, m = len(grid), len(grid[0])
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    path = [0] * (k + 1)
    dp = [[-1] * (k + 1) for _ in range(n + 1)]
    dp[1][1] = grid[0][0]

    for i in range(1, n + 1):
        for j in range(1, k + 1):
            for dx, dy in directions:
                ni, nj = i + dx, j + dy
                if 0 <= ni < n and 0 <= nj < m:
                    if dp[ni][nj] != -1:
                        dp[i][j] = min(dp[i][j], dp[ni][nj] + grid[i][j])

    return path[k:][::-1]
