import math

def max_fill(grid, capacity):
    rows, cols = len(grid), len(grid[0])
    buckets = [0] * rows
    max_wells_filled = 0

    for row in range(rows):
        for col in range(cols):
            if grid[row][col] == 1:
                buckets[row] += 1

    for row in range(rows):
        for col in range(cols):
            if grid[row][col] == 1:
                # Calculate the number of wells to fill
                wells_to_fill = math.ceil(buckets[row] / capacity)
                max_wells_filled = max(max_wells_filled, wells_to_fill)

    return max_wells_filled
