import math

def max_fill(grid, capacity):
    rows, cols = len(grid), len(grid[0])
    buckets = [grid[i][j] for i in range(rows) for j in range(cols) if grid[i][j] == 1]
    max_fill_count = 0

    while buckets:
        bucket_count = 0
        for i in range(rows):
            for j in range(cols):
                if buckets[i][j] == 1:
                    buckets[i][j] = 0
                    bucket_count += 1
        max_fill_count += bucket_count

        if capacity == 1:
            return max_fill_count
        elif capacity > 1:
            new_buckets = []
            for bucket in buckets:
                if bucket > 0:
                    new_buckets.append(bucket)
            buckets = new_buckets

    return max_fill_count
```

