def pluck(arr):
    if not arr:
        return []
    arr.sort()
    left, right = 0, len(arr) - 1
    while left < right:
        if arr[left] % 2 == 0:
            return [arr[left], left]
        if arr[right] % 2 == 0:
            return [arr[right], right]
        left += 1
        right -= 1
    return []
```

