import math
from functools import lru_cache

def max_fill(grid, capacity):
    @lru_cache(maxsize=None)
    def dfs(i, j, capacity):
        """
        You are given a rectangular grid of wells. Each row represents a single well,
        and each 1 in a row represents a single unit of water.
        Each well has a corresponding bucket that can be used to extract water from it, 
        and all buckets have the same capacity.
        Your task is to use the buckets to empty the wells.
        Output the number of times you need to lower the buckets.

        :param i: Current row index
        :param j: Current column index
        :param capacity: Maximum non-used capacity in buckets
        :return: Number of times lower the buckets
        """
        if i == len(grid):
            return 0
        if grid[i][j] == 0:
            return dfs(i + 1, j, capacity)
        v = grid[i][j]
        count, res = 0, 0
        for c in range(grid[i][j] + 1):
            new_capacity = capacity - v
            count1, res1 = dfs(i, j + c, new_capacity)
            count += count1
        sumr, sumc = 0, 0
        for c in range(len(grid)):
            for j in range(len(grid[0])):
                if c < len(grid) - 1 and grid[c + 1][j] == 1:
                    sumr -= grid[c][j]
                elif j < len(grid[0]) - 1 and grid[i][j + 1] == 1:
                    sumc -= grid[i][j]
            grid[i][j] = 0
            if sumr == 0 and sumc == 0:
                if count <= new_capacity:
                    return min(count + res1, res) if res1 < res1 + count else count + res
        return res
    return dfs(0, 0, capacity)
```

