def max_fill(grid: List[List[int]], capacity: int) -> int:
    rows, cols = len(grid), len(grid[0])
    wells = 0
    buckets = {}

    for r in range(rows):
        bucket_capacity += grid[r][0]
        for c in range(1, cols):
            if grid[r][c] == 1:
                buckets[r*c] = buckets.get(r*c, 0) + 1
                wells += 1

    used = 0
    max_wells = 0

    while buckets:
        for row, bucket_num in buckets.items():
            if bucket_num > 0 and len(grid[row]) > 0:
                # Use the buckets to extract as much water as possible from each well
                extraction_amount = min(bucket_num, capacity)
                capacity -= extraction_amount
                used += extraction_amount
                bucket_num -= extraction_amount
                if bucket_num == 0 and capacity == 0:  # If all buckets are empty
                    return used - 1
                if capacity == 0:  # If no more extraction is possible
                    max_wells = max(max_wells, used)
                    used = 0
                for col in range(cols):
                    if grid[row][col] == 1:
                        grid[row][col] = 0

    return -1
