def max_fill(grid, capacity):
    @lru_cache(maxsize=None)
    def dfs(i, j):
        if i < len(grid) and j < len(grid[0]):
            if grid[i][j]:
                return 1 + dfs(i + 1, j)
            else:
                return dfs(i + 1, j) * (capacity + 1)
        return 0
    return dfs(0, 0)
