import itertools

def get_row(lst, x):
    if not lst:
        return []
    if not isinstance(x, int):
        raise ValueError("x must be an integer")
    if not isinstance(lst, list) or not all(isinstance(row, list) for row in lst):
        raise ValueError("lst must be a 2D list")
    if not all(len(row) == len(lst[0]) for row in lst):
        raise ValueError("All rows must have the same number of columns")
    if not all(isinstance(y, int) for row in lst for y in row):
        raise ValueError("All elements in the list must be integers")
    return sorted([(i, j) for i, row in enumerate(lst) for j, x in enumerate(row) if x == x], key=lambda x: (lst.index(x), -x[1]))
```

