import math

def max_fill(grid, capacity):
    rows, cols = len(grid), len(grid[0])
    buckets = [[0] * cols for _ in range(rows)]
    max_fill_count = 0

    for row in range(rows):
        for col in range(cols):
            if grid[row][col] == 1:
                buckets[row][col] = 1
                max_fill_count += 1

    for row in range(rows):
        for col in range(cols):
            if buckets[row][col] == 0:
                continue
            bucket_index = row * cols + col
            while buckets[row][col] > 0 and bucket_index < len(buckets):
                buckets[row][col] -= 1
                bucket_index += cols

    return max_fill_count
```

