import math

def max_fill(grid, capacity):
    rows, cols = len(grid), len(grid[0])
    buckets = [[0]*cols for _ in range(rows)]
    max_count = 0

    for row in range(rows):
        for col in range(cols):
            if grid[row][col] == 1:
                buckets[row][col] = 1

    for row in range(rows):
        for col in range(cols):
            if buckets[row][col] == 0:
                continue
            count = 0
            while buckets[row][col] > 0:
                buckets[row][col] -= 1
                count += 1
                if count > capacity:
                    break
            max_count = max(max_count, count)

    return max_count
