from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    stack = []
    result = []
    parentheses = {'(': ')'}

    for char in paren_string:
        if char in parentheses:
            stack.append(char)
        elif char == ')':
            if stack:
                stack.pop()
            else:
                result.append(char)

    while stack:
        result.append(stack.pop())

    return result
```

