def largest_prime_factor(n: int):
    def prime_factors(n: int) -> list[int]:
        i = 2
        factors = []
        while i * i <= n:
            if n % i:
                i += 1
            else:
                n //= i
                factors.append(i)
        if n > 1:
            factors.append(n)
        return factors

    while n > 1:
        factors = prime_factors(n)
        max_factor = max(factors)
        if max_factor > n:
            return max_factor
        n = max(n, max_factor)
    return n
```

