def can_arrange(arr):
    if len(arr) < 2:
        return -1
    dp = [0] * len(arr)
    dp[0] = -1
    dp[1] = 0
    for i in range(2, len(arr)):
        if arr[i] <= arr[i - 1]:
            dp[i] = dp[i - 1]
        else:
            dp[i] = dp[i - 1] + 1
    return dp[-1]
