def match_parens(lst):
    stack = []
    for s in lst:
        if s == '(':
            stack.append(s)
        elif s == ')':
            if not stack:
                return 'No'
            stack.pop()
    return 'Yes' if not stack else 'No'
```

```python
def match_parens(lst):
    def is_good(s):
        stack = []
        for c in s:
            if c == '(':
                stack.append(c)
            elif c == ')':
                if not stack:
                    return False
                stack.pop()
        return not stack

    return 'Yes' if all(is_good(s) for s in lst) else 'No'
```

