def match_parens(lst):
    stack = [-1]
    for s in lst:
        if s == '(':
            stack.append(-1)
        elif s == ')':
            if stack[-1] == -1:
                return 'No'
            stack.pop()
    return 'Yes' if not stack else 'No'
