def hex_key(num):
    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    hex_digits = '0123456789ABCDEF'
    count = 0
    for digit in num.upper():
        if digit in hex_digits and is_prime(int(digit)):
            count += 1
    return count
```

