        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    hex_digits = '0123456789ABCDEF'
    count = 0
    for digit in num:
        if digit.isalpha():
            count += 1
        elif digit in hex_digits:
            if is_prime(int(digit)):
                count += 1
    return count
