from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    stack = []
    levels = []
    parenthesis_dict = {')': '(', '}': '{', ']': '['}

    for char in paren_string:
        if char in parenthesis_dict.values():
            stack.append(char)
        elif char in parenthesis_dict.keys():
            if not stack or stack.pop() != parenthesis_dict[char]:
                raise Exception('Invalid parentheses')

    while stack:
        levels.append(len(stack))

    return levels
```

