import numpy as np

def numerical_letter_grade(grades):
    if np.mean(grades) < 3.7:
        return ['E']
    elif np.mean(grades) < 3.3:
        return ['C+']
    elif np.mean(grades) < 3.0:
        return ['C']
    elif np.mean(grades) < 2.7:
        return ['D+']
    elif np.mean(grades) < 2.3:
        return ['D-']
    elif np.mean(grades) < 2.0:
        return ['C-']
    elif np.mean(grades) < 1.7:
        return ['D']
    elif np.mean(grades) < 1.3:
        return ['C-']
    elif np.mean(grades) < 1.0:
        return ['C']
    elif np.mean(grades) < 0.7:
        return ['D-']
    else:
        return ['A+']
```

