import math

def x_or_y(n, x, y):
    def is_prime(a):
        if a < 2:
            return False
        for i in range(2, int(math.sqrt(a)) + 1):
            if a % i == 0:
                return False
        return True

    if is_prime(n):
        return x
    else:
        return y
