```python
def prod_signs(arr):
    if not arr:
        return None
    sum_of_magnitudes = sum(abs(x) for x in arr)
    product_of_signs = 1
    for x in arr:
        product_of_signs *= -1 if x < 0 else 1
    return sum_of_magnitudes * product_of_signs
