def triples_sum_to_zero(l):
    seen = set()
    for num in l:
        if num in seen and num != 0:  # check if it's not zero
            for triple in [(num, num - 1, num - 2)]:
                if sum(triple) == 0:
                    return True
        seen.add(num)
    return False
```

