def is_equal_to_sum_even(n):
    def is_even(num):
        return num % 2 == 0

    def can_be_sum(n, target):
        if n < target:
            return False
        for i in range(1, target // 2 + 1):
            if target - i * 2 >= 0 and can_be_sum(target - i * 2, i):
                return True
        return False

    return can_be_sum(n, 4)
