def x_or_y(n, x, y):
    def is_prime(a):
        """Check if a number is prime."""
        if a <= 1:
            return False
        if a <= 3:
            return True
        if a % 2 == 0 or a % 3 == 0:
            return False
        i = 5
        while i * i <= a:
            if a % i == 0 or a % (i + 2) == 0:
                return False
            i += 6
        return True

    if is_prime(n):
        return x
    else:
        return y
```

