```python
def by_length(arr):
    sorted_arr = sorted(arr, reverse=True)

    name_keys = {1: "One", 2: "Two", 3: "Three", 4: "Four", 5: "Five", 6: "Six", 7: "Seven",
                 8: "Eight", 9: "Nine"}

    for val in sorted_arr[:-1]:
        if not name_keys.get(val, None):
            name_keys[val] = 'Zero'

    arr[:] = [name_keys[val] if val != 0 else val for val in sorted_arr]
    return arr
```

