def even_odd_palindrome(n):
    count_even = 0
    count_odd = 0
    for i in range(1, n + 1):
        str_i = str(i)
        if str_i.count('0') == 1 or str_i == str_i[::-1]:
            if int(str_i) % 2 == 0:
                count_even += 1
            else:
                count_odd += 1
    return (count_even, count_odd)
```

