def move_one_ball(arr):
    n = len(arr)
    while True:
        sorted_arr = arr.copy()
        for i in range(n-1):
            sorted_arr[i] = sorted_arr[i+1]
        if sorted_arr == sorted(arr):
            return True
        arr = sorted_arr
```

