def prime_length(string):
    import math
    if len(string) == 1:
        return True
    for i in range(2, len(string) + 1):
        if len(string) % i != 0 or math.gcd(len(string), i) != 1:
            return False
    return True
```

```python
def prime_length(string):
    def is_prime(n):
        if n <= 1:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        max_divisor = int(n**0.5) + 1
        for d in range(3, max_divisor, 2):
            if n % d == 0:
                return False
        return True

    length = len(string)
    return is_prime(length)
```

