import math

def prime_length(string):
    for length in range(2, len(string) + 1):
        if math.sqrt(length).is_integer():
            if len(string) % length == 0:
                return False
            for i in range(2, int(math.sqrt(length)) + 1):
                if length % i == 0:
                    return False
    return True
```

