def modp(n: int, p: int):
    if p == 0:
        raise ValueError("modp(P, 0) is undefined")
    if n < 0:
        n = n % p
    if n == 0:
        return 1
    temp = n
    result = 1
    while temp > 0:
        result = (result * temp) % p
        temp = temp >> 1
    return result
```

