def modp(n: int, p: int):
    """Return 2^n modulo p (be aware of numerics).
    """
    if p == 1:
        return 1
    if n == 0:
        return 1
    if n == 1:
        return p - 1
    m = modp(n // 2, p)
    if n % 2:
        return (m * m % p * 2 % p)
    else:
        return m * m % p
```

