def tri(n):
    def tribonacci_sequence(n):
        sequence = [1, 1, 1]
        while len(sequence) < n + 1:
            if n % 2 == 0:
                next_val = sequence[-1] + sequence[-2] + sequence[-3]
            else:
                next_val = sequence[-1] + sequence[-2] + sequence[-3] + sequence[-1]
            sequence.append(next_val)
        return sequence[:n + 1]

    if n >= 0:
        return tribonacci_sequence(n)
    else:
