def parse_nested_parens(paren_string: str) -> List[int]:
    def parse_parens(s: str) -> List[int]:
        stack = []
        levels = []
        for char in s:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if stack:
                    levels.append(len(stack) - 1)
                    stack.pop()
            elif char == ' ':
                continue
        return levels

    return [parse_parens(s) for s in paren_string.split()]

