import math

def max_fill(grid, capacity):
    n, m = len(grid), len(grid[0])
    if n == 1 or m == 1:
        return 0
    result = 0
    for i in range(n - 2, 0, -1):
        length = m - 2
        if length == 0:
            result += 1
            continue
        row = grid[i][m - 2]
        for j in range(len(grid[i - 1])):
            if grid[i - 1][j] == row:
                length -= 1
                if length == 0:
                    result += 1
                    break
    return result + math.ceil(n / capacity) * math.ceil(m / capacity) - 1
```

