def pluck(arr):
    if not arr:
        return []
    min_even = float('inf')
    min_index = float('inf')
    for i, value in enumerate(arr):
        if value % 2 == 0:
            if value < min_even:
                min_even = value
                min_index = i
            elif value == min_even:
                min_index = min(min_index, i)
    return [min_even, min_index]
