def Strongest_Extension(class_name, extensions):
    def strength(name):
        return sum(1 for c in name if c.isupper()) - sum(1 for c in name.lower() if c.islower())

    max_strength = max(strength(name) for name in extensions)
    strongest_extensions = [name for name in extensions if strength(name) == max_strength]
    return f"{class_name}.{strongest_extensions[0]}"
