from typing import List

def parse_music(music_string: str) -> List[int]:
    result = []
    beats = ['o', 'o|', '.|']
    for part in music_string.split('|'):
        if part in beats:
            result.append(4)
        elif part in ['o', '.']:
            result.append(1)
        else:
            result.append(0)
    return result
```

