import string

def get_closest_vowel(word):
    vowels = set(string.ascii_lowercase)
    closest_vowel = ""
    for i in range(len(word) - 1, -1, -1):
        if word[i] in vowels:
            if closest_vowel == "":
                closest_vowel = word[i]
            else:
                if abs(ord(closest_vowel) - ord(word[i])) < abs(ord(closest_vowel) - ord(vowels[0])):
                    closest_vowel = word[i]
    return closest_vowel
```

