import re

def get_closest_vowel(word):
    closest = ""
    for i in range(len(word) - 1, -1, -1):
        match = re.search('[aeiou]', word[i:])
        if match:
            if closest == "":
                closest = match.group()
            else:
                if match.group() > closest:
                    closest = match.group()
    return closest
```

