def get_closest_vowel(word):
    closest_vowel = ""
    for i in range(len(word) - 1, -1, -1):
        match = re.search('[aeiou]', word[i:])
        if match and (closest_vowel == "" or abs(i - len(word) - match.start()) < abs(i - len(word) - closest_vowel.start())):
            closest_vowel = word[i]
    return closest_vowel
