def is_happy(s):
    def check(s, i=0):
        if i == len(s):
            return True
        if i + 3 > len(s):
            return False
        for j in range(i + 1, i + 3):
            if s[j] == s[i]:
                return False
        return check(s, i + 3)

    return check(s)
