def is_happy(s):
    def is_happy_recursive(s, seen=None):
        if seen is None:
            seen = set()
        if len(s) <= 1:
            return True
        if s in seen:
            return False
        seen.add(s)
        for i in range(1, len(s)):
            if is_happy_recursive(s[:i] + s[i+1:], seen):
                return True
        return False

    return is_happy_recursive(s)
```

