def sort_array(arr):
    def helper(arr):
        n = len(arr)
        for i in range(1, n):
            for j in range(0, n-i):
                if bin(arr[j]).count('1') == bin(arr[j]+1).count('1'):
                    arr[i], arr[j] = arr[j], arr[i]
        return arr
    return helper(arr)
```

```python
def sort_array(arr):
    def count_ones(n):
        return bin(n).count('1')

    def compare(a, b):
        if count_ones(a) == count_ones(b):
            return a < b
        return count_ones(a) - count_ones(b)

    return sorted(arr, key=compare)
```

