def get_max_triples(n):
    a = [i * i - i + 1 for i in range(1, n + 1)]
    triples = set()
    for i in range(n):
        for j in range(i + 1, n):
            if (a[i] + a[j] + a[n]) % 3 == 0:
                triples.add((a[i], a[j], a[n]))
    return len(triples)
