def get_max_triples(n):
    factors = {}
    for i in range(1, n + 1):
        prime_factors = prime_factors_of(i)
        factors[i] = {}
        for p in prime_factors:
            if p in factors[i]:
                factors[i][p] += 1
            else:
                factors[i][p] = 1
    count = 0
    for a, count_a in factors[n].items():
        j, count_j = None, 0
        for a_prime, count_a_prime in factors[a].items():
            if a % a_prime == 0 and a * a_prime - a + a_prime > 0:
                count_j = count_a_prime
                j = a_prime
                if a / a_prime == 1:
                    break
            elif a * a_prime - a == 0:
                count_j = count_a_prime + count_j
                j = a_prime
    return count_j

def prime_factors_of(n):
    prime_factors = []
    i = 2
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n = n // i
            prime_factors.append(i)
    if n > 1:
        prime_factors.append(n)
    return prime_factors
```

