def even_odd_palindrome(n):
    even_count = 0
    odd_count = 0
    for i in range(1, n + 1):
        if i % 2 == 0:
            even_count += 1
        elif i % 10 == i // 10:
            odd_count += 1
    return even_count, odd_count
```

```python
def even_odd_palindrome(n):
    def is_palindrome(num):
        return str(num) == str(num)[::-1]

    even_count = 0
    odd_count = 0
    for i in range(1, n + 1):
        if is_palindrome(i):
            if is_palindrome(i + 1):
                even_count += 1
            else:
                odd_count += 1
    return (even_count, odd_count)
```

```python
def even_odd_palindrome(n):
    count_even = 0
    count_odd = 0
    for i in range(1, n + 1):
        if str(i) == str(i)[::-1] and i % 2 == 0:
            count_even += 1
        elif str(i) == str(i)[::-1] and i % 2 != 0:
            count_odd += 1
    return (count_even, count_odd)
```

```python
def even_odd_palindrome(n):
    count = 0
    for i in range(1, n+1):
        if i % 2 == 0 and str(i) == str(i)[::-1]:
            count += 1
        elif i % 2 != 0 and str(i) == str(i)[::-1]:
            count += 1
    return (count, count)
```

