def is_multiply_prime(a):
    def is_prime(x):
        if x < 2:
            return False
        for i in range(2, int(x**0.5) + 1):
            if x % i == 0:
                return False
        return True

    def multiply(a, b, c):
        if a < 0 or a > 100 or b < 0 or b > 100 or c < 0 or c > 100:
            return False
        if a == 0 or a == 1:
            return True
        if a == 2:
            return True
        if a == 3:
            return True
        if a % 2 == 0 or a % 3 == 0:
            return False

        for i in range(5, int(a**0.5) + 1, 6):
            if a % i == 0 or a % (i + 2) == 0:
                return False

        return True

    for i in range(2, a):
        if i % 3 == 0 or i % 5 == 0:
            return False
        if a % i == 0:
            return False
    return is_prime(a) and multiply(a-2, a-3, a-5)
