def max_fill(grid, capacity):
    rows, cols = len(grid), len(grid[0])
    buckets = [None] * rows
    times = 0

    for row in range(rows):
        for col in range(cols):
            if grid[row][col] == 0:
                if buckets[row] and buckets[row][col] == capacity:
                    buckets[row][col] = 0
                    times += 1
