import math

def max_fill(grid, capacity):
    rows, cols = len(grid), len(grid[0])
    buckets = [[0]*cols for _ in range(rows)]

    for row in range(rows):
        for col in range(cols):
            if grid[row][col] == 1:
                buckets[row][col] = capacity
                for r in range(row-1, -1, -1):
                    for c in range(col-1, -1, -1):
                        if r < rows and c < cols and grid[r][c] == 1:
                            buckets[row][col] = min(buckets[row][col], buckets[r][c])

    min_bucket = min(buckets[i][j] for i in range(rows) for j in range(cols))
    return rows*cols-min_bucket
