def minPath(grid, k):
    n = len(grid)
    dp = [[0] * n for _ in range(n)]
    dp[0][0] = grid[0][0]
    for i in range(1, n):
        dp[i][0] = grid[i][0]
    for j in range(1, n):
        dp[0][j] = grid[0][j]
    for i in range(1, n):
        for j in range(1, n):
            if i == n - 1:
                dp[i][j] = grid[i][j]
            else:
                dp[i][j] = grid[i][j] <= grid[i-1][j] and dp[i-1][j] or grid[i][j] <= grid[i][j-1] and dp[i][j-1]
    path = []
    i, j = n - 1, n - 1
    while i > 0 or j > 0:
        if i > 0 and j > 0:
            path.append(grid[i][j])
            if i > 0 and dp[i-1][j] < dp[i][j]:
                i -= 1
            if j > 0 and dp[i][j-1] < dp[i][j]:
                j -= 1
        elif i > 0:
            i -= 1
        elif j > 0:
            j -= 1
        else:
            break
    return path[::-1]
