import math

def compare_one(a, b):
    if isinstance(a, str):
        if isinstance(b, str):
            a, b = float(a), float(b)
        if math.isnan(a) and math.isnan(b):
            return None
        if math.isnan(a):
            return b
        elif math.isnan(b):
            return a
        return max(a, b)
    else:
        if math.isnan(a) and math.isnan(b):
            return None
        if math.isnan(a):
            return b
        elif math.isnan(b):
            return a
        return max(a, b)
```

