from typing import List, Tuple, TYPE_CHECKING
import statistics

if TYPE_CHECKING:
    from typing import List

def sum_product(numbers: List[int]) -> Tuple[int, int]:
    avg = statistics.mean(numbers)
    product = statistics.prod(numbers)
    return int(avg), int(product)
