```python
def is_happy(s):
    def helper(s, index):
        if index == len(s):
            return True
        if s[index] in s[index-1:index+1]:
            return False
        return helper(s, index+1)

    for i in range(2, len(s)):
        if helper(s, i):
            return False
    return True

print(is_happy("abcd"))  # Output: False
print(is_happy("aa"))    # Output: False
print(is_happy("abcdnbc"))  # Output: True
print(is_happy("abcda"))  # Output: False
print(is_happy("aabb"))   # Output: False
print(is_happy("adb"))   # Output: True
print(is_happy("xx"))    # Output: False
```

