def do_algebra(operator, operand):
    expression = []
    for sub_operator, operand_val in zip(operator, operand[1:]):
        if sub_operator == '+':
            expression.append(sub_operator)
            expression.append(operand_val)
        elif sub_operator == '-':
            expression.append(sub_operator)
            expression.append(-operand_val)
        elif sub_operator == '*':
            expression.append('*')
            expression.append(operand_val)
        elif sub_operator == '/':
            expression.append('/')
            expression.append(operand_val)
        elif sub_operator == '**':
            expression.append '**')
            expression.append(operand_val)
    # Calculate the final result
    if expression[0] == '/':
        result = 0
        for operand in expression[1:]:
            if operand == '+':
                result += operand_val
            elif operand == '-':
                result -= operand_val
            elif operand == '*':
                result *= operand_val
            elif operand == '**':
                result **= operand_val
                if operand_val == 0 and len(expression) > 1:
                    expression.pop()
        return result
    else:
        return expression[0]
