import math

def prime_fib(n: int):
    """
    prime_fib returns n-th number that is a Fibonacci number and it's also prime.
    """
    if n <= 0:
        return "Input should be a positive integer"
    elif n == 1:
        return 2
    elif n == 2:
        return 3
    else:
        fib = [2, 3]
        while len(fib) < n:
            next Fib_number = fib[-1] + fib[-2]
            fib.append(next(Fib_number) if fib[-1] <= fib[-2] and next(Fib_number) % 2 == 0 else next(Fib_number))
        if fib[-1] <= 1E9:
            return fib[-1]
        else:
            return "Fibonacci number generation has been stopped, incomplete sequence."
```

