def sort_array(arr):
    def helper(arr):
        if not arr:
            return []
        result = []
        ones = 0
        for i in arr:
            if i == 1:
                ones += 1
            else:
                result.append((i, ones))
        result.sort(key=lambda x: (x[0], -x[1]))
        return [i for i, _ in result]

    return helper(arr)
```

