def sort_array(arr):
    def binary_search(arr, target):
        left, right = 0, len(arr) - 1
        while left <= right:
            mid = (left + right) // 2
            if arr[mid] == target:
                return mid
            elif arr[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return -1

    def custom_sort(arr):
        for i in range(1, len(arr)):
            key = binary_search(arr, arr[i])
            if key != -1:
                arr[i], arr[key] = arr[key], arr[i]
        return arr

    return custom_sort(arr)
```

