        return []
    if not isinstance(x, int) or x < 0 or x >= len(lst):
        raise ValueError("Invalid input")
    if not lst[0]:
        return []
    sorted_lst = sorted(lst, key=lambda y: (y[0], -y[1]))
    coordinates = [(y[0], y[1]) for y in sorted_lst if y[0] == x]
    return coordinates
