def move_one_ball(arr):
    n = len(arr)
    for _ in range(n // 2):
        if arr[-1] > arr[-2]:
            break
        else:
            arr[-1] = arr[-2]
    return all(arr[i] <= arr[i + 1] for i in range(n - 1)) and arr[0] <= arr[1]
