def by_length(arr):
    def sort_by_digit(arr):
        sorted_arr = sorted(arr, reverse=True)
        name_dict = {i: "One" if i > 1 else "Zero" for i in range(1, 9)}
        return [name_dict[int(i)] if isinstance(i, int) else i for i in sorted_arr]

    def reverse(arr):
        return arr[::-1]

    if not arr:
        return []
    return sort_by_digit(reverse(sort_by_digit(arr)))
