import re

def by_length(arr):
    if not arr:
        return []
    arr.sort(key=lambda x: (len(str(abs(x))), x))
    common_prefix = [arr[0]]
    for num in arr[1:]:
        prefix = common_prefix[-1]
        match = re.match(r'^(.*?)\1+$', str(num))
        if match:
            new_num = match.group(0)
            while len(new_num):
                new_num = new_num[0] + new_num[-1]
                if len(new_num) != len(result_prefix[-1]):
                    new_num = new_num.ljust(len(result_prefix[-1]), '0')
                common_prefix.append(new_num)
        else:
            common_prefix.append(str(num))

    result_prefix = []
    for num in common_prefix:
        match = re.match(r'^(.*?)\1+$', num)
        if match:
            new_num = match.group(0)
            while len(new_num):
                new_num = new_num[0] + new_num[-1]
                if len(new_num) != len(result_prefix[-1]):
                    new_num = new_num.ljust(len(result_prefix[-1]), '0')
                result_prefix.append(new_num)
        else:
            result_prefix.append(num)

    return result_prefix[::-1]
