def exchange(lst1, lst2):
    while any(num % 2 != 0 for num in lst1) or any(num % 2 != 0 for num in lst2):
        for num in lst1:
            if num % 2 == 0:
                lst1.remove(num)
                lst2.append(num)
                break
        for num in lst2:
            if num % 2 == 0:
                lst1.append(num)
                lst2.remove(num)
                break
    return "YES" if all(num % 2 == 0 for num in lst1) else "NO"
```

