        if lst1[0] % 2 == 0 and lst2[0] % 2 == 0:
            lst1[0] = lst1[0] // 2
            lst2[0] = lst2[0] // 2
        else:
            return "NO"
    if len(lst1) == 0:
        return "YES"
    else:
        return "NO"
