def encode(message):
    result = ''
    for char in message:
        if char.isalpha():
            ascii_offset = 97 if char.islower() else 65
            result += chr((ord(char) - ascii_offset + 2) % 26 + ascii_offset)
        else:
            result += char
    return result
```

```python
def encode(message):
    words = ['xW'] if len(message) < 10 else None  # fail if too short of a message
    for i, char in enumerate(message.lower()):
        if i < len(words) and abs(ord(char) - ord(words[i])) == 2:
            message = message.replace(char, chr(ord(char) + 2))
            words[i] = None
    return message if words is None else message[:words[0].index('xW')]
```

