import string

def encode(message):
    encoded_message = ''
    for char in message:
        if char.lower() in string.ascii_lowercase:
            shift = min(25, ord(char.lower()) - 97 + 2)
            encoded_char = chr(97 + shift)
            encoded_message += encoded_char
        else:
            encoded_message += char
    return encoded_message
```

