def smallest_change(arr):
    left, right = 0, len(arr) - 1
    count = 0

    while left < right:
        if arr[left] != arr[right]:
            if (right - left + 1) == 1:
                count += 1
            else:
                left += 1
                right -= 1
        else:
            left += 1
            right -= 1

    return count
```

