def smallest_change(arr):
    n = len(arr)
    dp = [[0] * n for _ in range(n)]
    for gap in range(n):
        dp[gap][gap] = 0
    for gap1 in range(1, n):
        for gap2 in range(gap1):
            dp[gap1][gap2] = n - len(str(arr[gap1]))
            if gap2 > 0 and str(arr[gap1]) == str(arr[gap2]):
                dp[gap1][gap2] = min(dp[gap1][gap2], dp[gap1+1][gap2-1] + 1)
    return dp[0][n-1]
```

