```python
def circular_shift(x, shift):
    digits = [int(i) for i in str(x)]
    result = []
    for _ in range(shift):
        result.append(digits.pop(0))
    if shift > len(digits):
        result = result[::-1]
    return ''.join(map(str, result))
```

