import math

def intersection(interval1, interval2):
    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    start1, end1 = interval1
    start2, end2 = interval2

    if start1 >= start2 and end1 <= end2:
        intersection_range = (max(start1, start2), min(end1, end2))
    elif start1 < start2 and end1 > end2:
        intersection_range = (start1, min(end1, end2))
    else:
        intersection_range = (max(start1, start2), end1)

    intersection_length = intersection_range[1] - intersection_range[0]

    if is_prime(intersection_length):
        return "YES"
    else:
        return "NO"
```

