import numpy as np
from math import sqrt

def intersection(interval1, interval2):
    start = max(interval1[0], interval2[0])
    end = min(interval1[1], interval2[1])

    if start > end:
        start, end = end, start

    intersection_length = np.floor(sqrt(end - start ** 2))
    if intersection_length ** 2 == end - start ** 2:
        return "YES"
    else:
        return "NO"
```

```python
def intersection(interval1, interval2):
    start, end = sorted(interval1), sorted(interval2)
    intersection_len = 0
    if start[0] <= end[0] and start[1] <= end[1]:
        intersection_len = end[1] - start[0] + 1
    elif start[0] > end[0] or start[1] > end[1]:
        return False
    else:
        intersection_len = end[1] - start[0] + 1
    if intersection_len == 1 and intersection_len.is_integer():
        return "YES"
    else:
        return "NO"
```

