def is_happy(s):
    def is_distinct(s):
        return len(set(s)) == len(s)

    length = len(s)
    if length < 3:
        return False
    for i in range(length):
        if i + 1 < length and s[i] == s[i + 1]:
            return False
        if i + 2 < length and s[i] == s[i + 2]:
            return False
    return is_distinct(s)
