def smallest_change(arr):
    n = len(arr)
    dp = [[0] * n for _ in range(n)]
    for i in range(n):
        dp[i][i] = 0
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            dp[i][j] = float('inf')
            for k in range(i, j):
                if arr[i] == arr[k] and dp[i][k + 1] != float('inf'):
                    dp[i][j] = min(dp[i][j], dp[i][k] + 1)
    return dp[0][n - 1]
```

