def closest_integer(value):
    num = float(value)
    rounded = round(num)
    if rounded == num:
        if num > 0:
            return rounded + 1
        else:
            return rounded - 1
    if abs(num - rounded) < abs(num - rounded - 1):
        return rounded
    else:
        return rounded + 1
