import math

def is_multiply_prime(a):
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(math.sqrt(n)) + 1):
            if n % i == 0:
                return False
        return True

    factors = []
    for i in range(2, a + 1):
        if a % i == 0 and is_prime(i):
            factors.append(i)
        if len(factors) == 3 and a // math.prod(factors) == 1:
            return True
    return False
```

