def pluck(arr):
    if not arr:
        return []
    min_even_idx = None
    min_even_val = float('inf')
    for i, val in enumerate(arr):
        if val % 2 == 0:
            if val < min_even_val:
                min_even_val = val
                min_even_idx = i
            elif val == min_even_val:
                if i < min_even_idx:
                    min_even_idx = i
    return [min_even_val, min_even_idx] if min_even_val != float('inf') else []
```

