def modp(n: int, p: int):
    if n == 0:
        return 1
    dp = [0] * (n + 1)
    dp[0] = 1
    for i in range(1, n + 1):
        for j in range(1, min(i, p)):
            dp[i] += dp[i - j] * (p - j) ** ((i - j) // p)
    return dp[n]
```

