def circular_shift(x, shift):
    num_str = str(x)
    result = []
    for i in range(len(num_str)):
        digit = int(num_str[i])
        if shift >= len(num_str):
            shift -= len(num_str)
        result.append(digit << shift)
    return ''.join(map(str, result))
