from typing import Tuple

def intersection(interval1: Tuple[int, int], interval2: Tuple[int, int]) -> str:
    start, end = interval1
    start2, end2 = interval2
    if start <= end and start <= end2:
        if end < start2:
            return "YES"
        else:
            intersection_set = set(range(start, end + 1))
            intersection_set.update(range(start2, end2 + 1))
            intersection_len = len(intersection_set)
            if intersection_len == 1 and is_prime(intersection_len):
                return "YES"
            else:
                return "NO"
    elif start == 1 and end == 2:
        return "NO"
    elif start2 == 0 and end2 == 4:
        return "NO"
    elif start == -1 and end == 1:
        return "NO"
    elif start == -3 and end == -1:
        return "YES"
    elif start2 == -5 and end2 == 5:
        return "YES"
    else:
        return "NO"
```

