    def distance(x: float, y: float) -> float:
        return ((x - y) ** 2) ** 0.5

    for i in range(len(numbers)):
        for j in range(i + 1, len(numbers)):
            if distance(numbers[i], numbers[j]) <= threshold:
                return True
    return False
