from typing import List


def parse_music(music_string: str) -> List[int]:
    def parse_single_note(note: str) -> int:
        """
        Recursively parse a single note in the music string.

        Args:
        note: The note to be parsed.

        Returns:
        The duration of the note in beats.
        """
        if note in ['.', '|']:
            return int(note)
        elif note == 'o':
            return 4
        elif note == 'o|':
            return 2
        elif note == '|':
            return 1
        elif note in notes:
            return notes[note]
        else:
            return int(note)

    return [parse_single_note(note) for note in music_string.split() if note]

