from typing import List

def parse_music(music_string: str) -> List[int]:
    result = []
    temp_str = music_string
    for char in temp_str:
        if char == 'o':
            result.extend([0, 0])
        elif char == '|':
            result.extend([1, 0])
        elif char == '.':
            result.extend([0, 1, 0, 0])
        elif char == '|':
            result.extend([1, 0, 0, 0])
        elif char == 'o|':
            result.extend([0, 0, 1, 0])
        elif char == 'o ':
            result.extend([0, 1, 0])
        elif char == ' .|':
            result.extend([1, 1, 0])
        elif char == ' .| ':
            result.extend([0, 0, 1, 1])
        elif char == ' ail':
            result.extend([1, 0, 1, 0])
        elif char == ' ail ':
            result.extend([0, 0, 1, 1])
        elif char == '.' |:
            result.extend([0, 0, 1, 0])
        else:
            raise ValueError("Invalid music note in the string")
    return result
