def is_happy(s):
    def helper(s, i=0, seen=set()):
        if i == len(s):
            return True
        if s[i] in seen:
            seen.add(s[i])
            return False
        seen.add(s[i])
        if helper(s, i + 1, seen):
            return True
        return False

    return helper(s)
```

