def is_happy(s):
    seen = set()
    for i, c in enumerate(s):
        if c in seen:
            return False
        seen.add(c)
        if i >= len(s) - 2 and c != s[i-2] and c != s[i-1]:
            return False
    return True
```

```python
def is_happy(s):
    def helper(s, level=0):
        if len(s) <= 2:
            return True
        for i in range(len(s) - 1):
            if s[i] == s[i + 1]:
                if level != 0:
                    return False
                helper(s[i + 1:], level + 1)
        return True

    return helper(s)

