def is_happy(s):
    def helper(s):
        stack = s
        while stack:
            if len(stack) < 3:
                return False
            else:
                top = stack.pop()
                if len(stack) < 3:
                    stack.append(top)
                else:
                    if top * 10 + stack[0] == stack[1] and len(stack) == 3:
                        stack.pop()
                        stack.pop()
                        stack.pop()
                    else:
                        return False
        return True

    return helper(s)
```

