from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    """ Input to this function is a string containing multiple groups of nested parentheses. 
    Your goal is to separate those group into separate strings and return the list of those.
    Separate groups are balanced (each open brace is properly closed) and not nested within each other
    Ignore any spaces in the input string.
    >>> separate_paren_groups('( ) (( )) (( )( ))')
    ['()', '(())', '(()())']
    """
    def backtracking(string: str, left: int, right: int) -> List[str]:
        if not string:
            return ['']

        if string[0] in '({[':
            left = 0
            right = right + 1
            sub_str = string[0]
            result = backtracking(string[1:], left, right)
        else:
            sub_str = string[0]
            result = backtracking(string[1:], left + 1, right)
            if sub_str == '(':
                right += 1
            elif sub_str == ')':
                left += 1
            elif sub_str == '[':
                left += 1
                right += 2
            else:
                result.insert(0, '(')
                result.extend(backtracking(string[1:], left, right))

        return result

    return backtracking(paren_string, 0, 0)

