from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    def backtrack(open_braces: int, close_braces: int, current_str: str) -> List[str]:
        if not current_str:
            result.append(current_str)
            return

        if open_braces < 0:
            return

        if close_braces > 0:
            if open_braces == close_braces:
                result.append(current_str)
                backtracks = backtrack(open_braces - 1, close_braces - 1, current_str + '(')
                for batch in backtracks:
                    result.append('' if batch == '(' else '(')
                result.append(current_str + ')')
            else:
                return

        if open_braces < close_braces:
            return

        if close_braces < open_braces:
            return

        open_braces -= 1
        close_braces -= 1
        backtrack(open_braces, close_braces, current_str + ' ')

    result = []
    backtrack(0, 0, '')
    return result
```

