def match_parens(lst):
    def Helper(open_parens, close_parens, curr_str):
        if not curr_str:
            if open_parens == close_parens:
                return True
            return False
        if curr_str[0] == '(':
            closing_brace = False
            for char in lst:
                if char == ')':
                    closing_brace = True
                    if Helper(open_parens + 1, close_parens - 1, curr_str[1:]) != True:
                        return False
            if not closing_brace:
                open_parens += 1
                return True
        return Helper(open_parens, close_parens, curr_str[1:])

    return 'Yes' if Helper(0, 0, '') else 'No'
```

