def encrypt(s):
    rot = 2 * len(s) - 1
    encrypted = ""
    for char in s:
        if char.isalpha(): 
            ascii_offset = ord('a') if char.islower() else ord('A')
            encrypted += chr((ord(char) - ascii_offset + rot) % 26 + ascii_offset)
        else:
            encrypted += char
    return encrypted
