def Strongest_Extension(class_name, extensions):
    def name(width):
        return ''.join(a for a in c if a.isalpha() and a.isupper() or a.islower()) for c in c[:width])

    def score(ext):
        return name(len(ext)).count('-') - name(len(ext)).count('')

    max_score, strongest_ext = float('inf'), None
    for ext in extensions:
        score_val = score(ext)
        if score_val < max_score:
            max_score, strongest_ext = score_val, ext

    return f'{class_name}.{strongest_ext}'
