import math

def car_race_collision(n: int):
    collisions = 0
    for i in range(n):
        for j in range(n):
            if (i + 1) % (2 * n) == j % (2 * n):
                collisions += 1
    return collisions
```

```python
def car_race_collision(n: int):
    collisions = 0
    while n > 0:
        car1 = -n
        car2 = n
        while car1 >= 0 or car2 >= 0:
            if car1 == car2:
                collisions += 1
                car1, car2 = -car1, -car2
            elif car1 > car2:
                car1 -= 1
            else:
                car2 -= 1
    return collisions
```

