def cycpattern_check(a, b):
    # Check if 'b' is a substring of 'a'
    if b in a:
        # If 'b' is a substring, check if any of its rotations are substrings of 'a'
        for i in range(len(b)):
            # Rotate 'b' by i places in 'a'
            rotated_b = b[i:] + b[:i]
            # Check if 'rotated_b' is a substring of 'a'
            if rotated_b in a:
                return True
    return False
