def get_closest_vowel(word):
    vowels = 'aeiouAEIOU'
    index_vowels = [i for i, x in enumerate(word) if x in vowels]
    if not index_vowels:
        return ""
    row_len = min(len(index_vowels), 3)
    return '-'.join(word[i-1] if i > 0 else word[i] for i in (index_vowels[i-1:i+1])[:row_len])
