import string

def encode(message):
    alphabet = list(string.ascii_lowercase)
    result = ''
    for char in message:
        if char.isalpha():
            index = alphabet.index(char.lower())
            if char.isupper():
                result += alphabet[(index + 2) % 26].upper()
            else:
                result += alphabet[(index + 1) % 26]
        else:
            result += char
    return result
```

