def is_equal_to_sum_even(n):
    def is_even(num):
        return num % 2 == 0

    def can_form_sum_even(remaining_sum, even_count):
        if remaining_sum == 0:
            return even_count == 0
        for i in range(1, remaining_sum + 1):
            if is_even(i) and can_form_sum_even(remaining_sum - i, even_count + 1):
                return True
        return False

    for i in range(2, n // 2 + 1):
        if can_form_sum_even(n - i * 2, i):
            return True
    return False
```

