def is_equal_to_sum_even(n):
    def helper(x):
        if x < 0:
            return False
        even_sum = 0
        for i in range(1, x + 1):
            if i % 2 == 0 and x - i >= 0:
                even_sum += i
        return even_sum == x

    return helper(2) or helper(4) or helper(6)
