def minPath(grid, k):
    N = len(grid)
    visited = set()
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]  # right, down, left, up
    def dfs(x, y):
        if x < 0 or x >= N or y < 0 or y >= N or (x, y) in visited:
            return
        visited.add((x, y))
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            for val in [grid[x][y]]:
                dfs(nx, ny)
        min_val = float('inf')
        for val in grid[x][y:]:
            min_val = min(min_val, val)
        if min_val == float('inf'):
            return
        grid[x][y] = min_val
    dfs(0, 0)
    min_val = 0
    path = []
    for val in reversed(grid[0][0]):
        if val == min_val:
            path.append(val)
            min_val = float('inf')
    for val in reversed(grid):
        if val == min_val:
            path.insert(0, val)
            min_val = float('inf')
    return path
