def do_algebra(operator, operand):
    """
    Given two lists operator, and operand. The first list has basic algebra operations, 
    and the second list is a list of integers. Use the two given lists to build the 
    algebraic expression and return the evaluation of this expression.

    The basic algebra operations:
    Addition ( + ) 
    Subtraction ( - ) 
    Multiplication ( * ) 
    Floor division ( // ) 
    Exponentiation ( ** ) 

    Example:
    operator['+', '*', '-']
    array = [2, 3, 4, 5]
    result = 2 + 3 * 4 - 5
    => result = 9

    """
    result_dict = {}
    variables = set(range(len(operator))) + set(range(len(operand)))
    numVar = 1

    for i in variables:
        for op in operator:
            if op == '+':
                result_dict[str(i)] = result_dict.get(str(i), 0) + operand[i]
            elif op == '-':
                result_dict[str(i)] = result_dict.get(str(i), 0) - operand[i]
            elif op == '*':
                result_dict[str(i)] = result_dict.get(str(i), 0) * operand[i]
            elif op == '/':
                if operand[i] == 0:
                    raise ValueError("Cannot divide by zero")
                result_dict[str(i)] = result_dict.get(str(i), 0) // operand[i]
            elif op == '**':
                result_dict[str(i)] = result_dict.get(str(i), 0) ** operand[i]

    def evaluate_expression(expression):
        numVar += 1
        def collect_variables(v):
            if isinstance(v, int):
                return 1
            for key, value in result_dict.items():
                if key in v:
                    return collect_variables(v[key])
            return 0
        return sum(collection(numVar) * coeff for coeff, numVar in collect_variables(expression))

    return evaluate_expression(list(result_dict.keys()))
