    def can_beWrittenAsSumOfEvenNumbers(n):
        for i in range(1, int(n/2)+1):
            if n % i == 0 and is_even(i) and is_even(n-i):
                return True
        return False

    return can_beWrittenAsSumOfEvenNumbers(n)
