def fib4(n: int):
    if n <= 4:
        return fib4_helper(n)
    else:
        return fib4_helper(n) + fib4(n-1) + fib4(n-2) + fib4(n-3)

def fib4_helper(n: int):
    if n == 0:
        return 0
    elif n == 1:
        return 0
    elif n == 2:
        return 2
    elif n == 3:
        return 0
    else:
        return fib4_helper(n-1) + fib4_helper(n-2) + fib4_helper(n-3)
