def is_happy(s):
    def is_distinct(lst, index):
        if len(lst) <= 2: return True
        stack = lst[:]
        for i in range(len(stack)):
            if i >= index + 2:
                return False
            if stack[i] in stack[i - 1:i + 1]:
                return False
            stack[i], stack[i - 1] = stack[i - 1], stack[i]
        return True

    if len(s) < 3: return False
    k = 0
    for i in range(len(s)): k = s[i] if k < s else is_distinct(s[:k] + s[k + 1:], i)
    return k >= len(s) - 1
```

