def file_name_check(file_name):
    import re
    patterns = ['^[a-zA-Z][\w]*$', '[a-zA-Z][\w]*.', r'[a-zA-Z][\w]*\.[txt\.exe\.dll]$']
    for pattern in patterns:
        if re.match(pattern, file_name):
            return 'Yes'
    return 'No'
```

```python
def file_name_check(file_name):
    if any(digit in file_name for digit in '0123456789') or '0' in file_name:
        return 'No'
    elif any(char.isalpha() for char in file_name[:file_name.find('.')] if char.isalpha()) and len(file_name[:file_name.find('.')]) > 1:
        return 'Yes'
    elif any('.' in file_name[:file_name.find('.')] for _ in range(file_name.find('.'))) and any(substring in ['txt', 'exe', 'dll'] for substring in file_name[file_name.find('.'):]):
        return 'Yes'
    else:
        return 'No'
```

