def is_nested(string):
    stack = []
    bracket_map = {')': '(', ']': '[', '}': '{'}
    for char in string:
        if char in ['(', '[', '{']:
            stack.append(char)
        elif char in [')', ']', '}']:
            if not stack or stack.pop() != bracket_map[char]:
                return False
    return stack
