def prime_fib(n: int):
    def is_prime(num: int) -> bool:
        if num < 2:
            return False
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                return False
        return True

    fib_numbers = [2, 3]
    while len(fib_numbers) < n:
        fib_numbers.append(fib_numbers[-1] + fib_numbers[-2])
    return fib_numbers[-1] if is_prime(fib_numbers[-1]) else None
```

```python
def prime_fib(n: int):
    def is_prime(num: int) -> bool:
        if num < 2:
            return False
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                return False
        return True

    fib_nums = [2, 3]
    while len(fib_nums) < n:
        next_num = fib_nums[-1] + fib_nums[-2]
        if is_prime(next_num):
            fib_nums.append(next_num)
    return fib_nums[-1]
```

