def sort_array(arr):
    def custom_sort(x):
        inversions = 0
        for i in range(len(x)):
            for j in range(i+1, len(x)):
                if x[i] > x[j] or (x[i] == x[j] and x[i] < 0):
                    inversions += 1
                    x[i], x[j] = x[j], x[i]
        return inversions

    arr.sort(key=lambda x: (x.count("1"), -x))

    return arr
```

