def is_multiply_prime(a):
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    def is_product_of_primes(n):
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0 and is_prime(i) and is_prime(n // i):
                return True
        return False

    return is_product_of_primes(a)
```

