def smallest_change(arr):
    n = len(arr)
    dp = [[0] * n for _ in range(n)]
    arr = [0] + arr + [0]
    for i in range(1, n):
        for j in range(i):
            if arr[i] == arr[j]:
                dp[i][j] = dp[j+1][j] + 1
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])
    return dp[n-1][n-1]
```

