def smallest_change(arr):
    n = len(arr)
    dp = [[0] * n for _ in range(n)]
    min_steps = [[float('inf')] * n for _ in range(n)]
    min_steps[0][0] = 0
    for i in range(n):
        for j in range(i + 1):
            if arr[i] == arr[i] and j == 0:
                min_steps[i][j] = 0
            elif arr[i] != arr[i]:
                min_steps[i][j] = min_steps[i + 1][j] + 1
            else:
                min_steps[i][j] = min(min_steps[i + 1][j], min_steps[i][j + 1])
    return min_steps[n - 1][0]
