import re

def by_length(arr):
    sorted_arr = sorted(arr, reverse=True)
    digit_map = {
        'One': 'One', 'Two': 'Two', 'Three': 'Three', 'Four': 'Four', 'Five': 'Five', 
        'Six': 'Six', 'Seven': 'Seven', 'Eight': 'Eight', 'Nine': 'Nine'
