def even_odd_palindrome(n):
    def is_palindrome(num):
        return str(num) == str(num)[::-1]

    even_count = 0
    odd_count = 0
    for i in range(1, n+1):
        if is_palindrome(i):
            if is_palindrome(i+1):
                even_count += 1
            else:
                odd_count += 1
    return (even_count, odd_count)
```

```python
def even_odd_palindrome(n):
    count = 0
    for i in range(1, n + 1):
        if str(i) == str(i)[::-1] and i % 2 == 0:
            count += 1
        if str(n - i) == str(n - i)[::-1] and (n - i) % 2 == 0:
            count += 1
    return count, count
```

