import math

def bf(planet1, planet2):
    planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]
    if planet1 not in planets or planet2 not in planets:
        return ()
    else:
        distances = sorted([(abs(math.radians(planet2) - math.radians(planet1)), planet) for planet in planets if planet != planet1 and planet != planet2])
        return tuple(planet for _, planet in distances)
