import numpy as np

def sort_array(array):
    array_compared = np.concatenate((array, array), axis=1)
    sorted_indices = np.where(np.sum(array_compared, axis=0) % 2 != 0)[0]
    sorted_array = array_copy = array.copy()
    for idx in sorted_indices:
        sorted_array[idx] = sorted_array.pop(sorted_indices[idx])
    return np.concatenate((sorted_array, array_copy), axis=1)

def array_copy(arr):
    return arr.copy()
