import math

def skjkasdkd(lst):
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(math.sqrt(num)) + 1):
            if num % i == 0:
                return False
        return True

    largest_prime = None
    for num in lst:
        if is_prime(num):
            largest_prime = num
        else:
            for i in range(num, 0, -1):
                if num % i == 0 and is_prime(i):
                    largest_prime = i
                    break
    return sum(int(digit) for digit in str(largest_prime))
```

