import itertools

def get_row(lst, x):
    if not lst or not x:
        return []

    keys = set(tuple(row.keys()) for row in lst)
    num_cols = max(columns for row in lst for columns in zip(*row) if isinstance(columns, tuple)) + 1

    for key in keys:
        for i, column in enumerate(itertools.cycle(range(num_cols)), start=1):
            if key in list(column):
                for row_col in sorted(zip(*lst), key=lambda y: (-y[i], -y[i+1])):
                    if tuple(y) == key:
                        return [(row_col[0], row_col[1]) for row_col in sorted(row_col)]

    return []

