import math

def skjkasdkd(lst):
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(math.sqrt(n)) + 1):
            if n % i == 0:
                return False
        return True

    max_prime = float('-inf')
    for n in lst:
        if is_prime(n):
            max_prime = max(max_prime, n)

    return sum([int(str(n)[0]) for n in lst if n > max_prime and is_prime(n)])
```

