        if n <= 1:
            return False
        for i in range(2, int(math.sqrt(n)) + 1):
            if n % i == 0:
                return False
        return True

    largest_prime = None
    prime_digit_sum = 0
    for num in lst:
        if is_prime(num):
            if largest_prime is None or num > largest_prime:
                largest_prime = num
                prime_digit_sum = sum(int(digit) for digit in str(num))
