def count_up_to(n):
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                return False
        return True

    prime_candidate = n
    primes = []
    while len(primes) < n:
        if is_prime(prime_candidate) and prime_candidate < n:
            primes.append(prime_candidate)
        prime_candidate += 1

    return primes
