def do_algebra(operator, operand):
    if len(operator) == len(operand) - 1:
        raise ValueError("Invalid operand length")
    result = 0
    for i, op in enumerate(operator):
        if op == '+':
            result += operand[i + 1]
        elif op == '-':
            result -= operand[i + 1]
        elif op == '*':
            result *= operand[i + 1]
        elif op == '//':
            result //= operand[i + 1]
        elif op == '**':
            result = result ** operand[i + 1]
    return result
```

