import itertools

def get_row(lst, x):
    if not lst:
        return []
    if not isinstance(x, int):
        raise ValueError("x must be an integer")
    if not all(isinstance(row, list) for row in lst):
        raise ValueError("lst must be a list of lists")
    if not all(len(row) == len(lst[0]) for row in lst):
        raise ValueError("All rows must have the same number of columns")
    if not all(isinstance(col, int) for row in lst for col in row):
        raise ValueError("All columns must be integers")
    if not all(0 <= col < len(row) for col in range(len(row[0]))):
        raise ValueError("Columns must be between 0 and the number of rows")
    return sorted([(i, j) for i, row in enumerate(lst) for j, col in enumerate(row) if col == x], key=lambda x: (lst.index(x), -x))
