from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    parentheses_list = []
    count_dict = {')': 0, '}': 0, ']': 0}
    for char in paren_string:
        if char == '(':
            parentheses_list.append('(')
        elif char == '{':
            parentheses_list.append('{')
        elif char == '[':
            parentheses_list.append('[')
        elif char in count_dict.values():
            parentheses_list.append(char)
        else:
            if not parentheses_list or parentheses_list[-1] != '(' and parentheses_list[-1] != '{' and parentheses_list[-1] != '[':
                parentheses_list.append(char)
    return [paren_string[i:j] for i, j in [(0, len(paren_groups)) for paren_groups in parentheses_list[::-1]]]

