from typing import List, Tuple

def rolling_max(numbers: List[int]) -> List[int]:
    max_list = []
    max_val = float('-inf')
    start = 0
    for end in range(len(numbers)):
        if numbers[end] > max_val:
            max_val = numbers[end]
            max_list.append(max_val)
        elif numbers[end] == max_val:
            max_list[end - start + 1] = max_val
        if end >= len(numbers) - 2:
            break
    return max_list
```

