from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    output = []
    stack = []
    for char in paren_string:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if stack:
                # A pair is detected - pop the last opening
                last_exceptioned = stack.pop()
                output.append(last_exceptioned if last_exceptioned == '(' else '(' + last_exceptioned + ')')
            else:
                output.append('X(')
        else:
            stack.append(char)
    while stack:
        output.append('X(' + stack.pop + ')')
    return output
