def even_odd_palindrome(n):
    count = [0, 0]
    for i in range(1, n+1):
        num = str(i)
        if num == num[::-1]: 
            if num.count('0') != 1: 
                if num == str(i)[::-1]: 
                    count[0] += 1
                else: 
                    count[1] += 1
    return (count[0], count[1])
```

