def even_odd_palindrome(n):
    palindrome_counts = {}
    even_count = 0
    odd_count = 0
    for num in range(1, n + 1):
        if is_palindrome(num):
            palindrome_counts[num] = palindrome_counts.get(num, 0) + 1
            if num % 2 == 0:
                even_count += palindrome_counts[num]
            else:
                odd_count += palindrome_counts[num]
    return even_count, odd_count

def is_palindrome(num):
    return str(num) == str(num)[::-1]
