def generate_integers(a, b):
    def generate_integers_recursive(num):
        if num >= b:
            return []
        elif num >= a:
            return [num] + generate_integers_recursive(num + 1)
        else:
            even_digits = [int(d) for d in str(num) if int(d) % 2 == 0]
            return even_digits + generate_integers_recursive(num + 1)

    return generate_integers_recursive(a)

print(generate_integers(2, 8))  # [2, 4, 6, 8]
