def smallest_change(arr):
    dp = [[0] * len(arr) for _ in range(len(arr))]
    for i in range(len(arr)):
        dp[i][i] = 0
    for length in range(2, len(arr) + 1):
        for i in range(len(arr) - length + 1):
            j = i + length - 1
            if arr[i] == arr[j]:
                dp[i][j] = dp[i + 1][j - 1]
            else:
                dp[i][j] = 1 + min(dp[i + 1][j], dp[i][j - 1])
    return dp[0][len(arr) - 1]
```

```python
def smallest_change(arr):
    n = len(arr)
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        dp[i][i] = 0
    for i in range(n + 1):
        for j in range(i + 1, n + 1):
            if arr[i - 1] == arr[j - 1]:
                dp[i][j] = dp[i + 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])
    return n - dp[n][n]
```

```python
def smallest_change(arr):
    n = len(arr)
    dp = [[0 for _ in range(n)] for _ in range(n)]

    for gap in range(n):
        dp[gap][gap] = 1
        if gap > 0 and arr[gap] == arr[gap - 1]:
            dp[gap][gap] = dp[gap - 1][gap - 1]

    for gap in range(n - 1, -1, -1):
        for i in range(n - gap - 1):
            j = i + gap
            dp[gap][i] = min(dp[gap + 1][i] + 1, dp[gap][j] + 1, dp[gap + 1][j])

    return dp[0][0]
```

