def modp(n: int, p: int):
    result = 1
    while p:
        if p & 1:
            result = (result * n) % p
        n = (n * n) % p
        p >>= 1
    return result
```

```python
def modp(n: int, p: int):
    if n >= p:
        return 0
    result = 1
    while n > 0:
        if n % 2 == 1:
            result = (result * p) % p
        n = n // 2
        p = p * p % p
    return result
```

