def bf(planet1, planet2):
    planet_names = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]
    planets_in_range = []
    for planet in planet_names:
        if planet == planet1 or planet == planet2:
            continue
        if planet == planet1:
            lower_bound = planet
        else:
            lower_bound = planet2
        upper_bound = planet_names
        sorted_planets = sorted(upper_bound)
        for i in range(len(sorted_planets)):
            if sorted_planets[i] >= lower_bound:
                planets_in_range.append(sorted_planets[i])
                break
    return tuple(sorted(planets_in_range))
```

