import re

def bf(planet1, planet2):
    planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]
    regex = re.compile(rf"^{planet1}(?:-{planet2})*$")
    match = regex.match(planet1)
    if not match:
        return ()
    rlist = [p[0] for p in planets if p in planets[match.start():match.end()] + planets[match.end():match.start()] if p not in planets[match.end():match.start()] + planets[:match.end()] + planets[match.end():match.start()]]
    rlist.sort(key=lambda p: planets.index(p))
    return tuple(rlist)
```

