    if planet1 in planets and planet2 in planets:
        closest = []
        if planet1 > planet2:
            for planet in planets:
                if planet not in closest and planet >= planet1 and planet <= planet2:
                    closest.append(planet)
        else:
            for planet in planets:
                if planet not in closest and planet <= planet1 and planet >= planet2:
                    closest.append(planet)
        return tuple(sorted(closest))
    else:
        return ()
